<?php
session_start();
if (empty($_SESSION['usuario_id']) || ($_SESSION['usuario_rol'] ?? '') !== 'admin') { http_response_code(403); exit('Acceso restringido.'); }
require_once __DIR__.'/../backend/conexion.php';
if (empty($_SESSION['csrf_admin'])) $_SESSION['csrf_admin']=bin2hex(random_bytes(32));
$csrf=$_SESSION['csrf_admin']; $message='';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,$_POST['csrf']??'')){http_response_code(419);exit('Token inválido.');}
 $id=(int)($_POST['producto_id']??0);$sku=trim($_POST['sku']??'');$brand=trim($_POST['marca']??'Xiaomi');$old=($_POST['precio_anterior']??'')!==''?(float)$_POST['precio_anterior']:null;$warranty=trim($_POST['garantia']??'');$spec=trim($_POST['especificaciones']??'{}');$gallery=trim($_POST['galeria']??'[]');$featured=isset($_POST['destacado'])?1:0;
 if(!$id){$message='Selecciona un producto.';}elseif(!is_array(json_decode($spec,true))||json_last_error()!==JSON_ERROR_NONE){$message='Las especificaciones deben ser JSON válido.';}elseif(!is_array(json_decode($gallery,true))||json_last_error()!==JSON_ERROR_NONE){$message='La galería debe ser un arreglo JSON válido.';}else{
  $q=$pdo->prepare('INSERT INTO producto_detalles(producto_id,sku,marca,precio_anterior,garantia,especificaciones,galeria,destacado) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE sku=VALUES(sku),marca=VALUES(marca),precio_anterior=VALUES(precio_anterior),garantia=VALUES(garantia),especificaciones=VALUES(especificaciones),galeria=VALUES(galeria),destacado=VALUES(destacado)');
  $q->execute([$id,$sku?:null,$brand?:'Xiaomi',$old,$warranty?:null,$spec,$gallery,$featured]);
  $a=$pdo->prepare('INSERT INTO auditoria_admin(admin_id,accion,entidad,entidad_id,detalle) VALUES(?,?,?,?,?)');$a->execute([$_SESSION['usuario_id'],'actualizar_ficha_producto','producto_detalles',$id,'Ficha técnica actualizada']);$message='Ficha técnica guardada.';
 }
}
$products=$pdo->query('SELECT p.id,p.nombre,p.precio,d.sku,d.marca,d.precio_anterior,d.garantia,d.especificaciones,d.galeria,d.destacado FROM productos p LEFT JOIN producto_detalles d ON d.producto_id=p.id ORDER BY p.nombre')->fetchAll();
$selected=(int)($_GET['id']??($_POST['producto_id']??0));$current=null;foreach($products as $x){if((int)$x['id']===$selected){$current=$x;break;}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fichas técnicas | Xiaomi Store</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f6f8;font:15px Arial;color:#222}.top{background:#171717;color:white;padding:18px 5%}.top a{color:white;margin-right:18px}.wrap{max-width:1050px;margin:28px auto;padding:0 18px}.panel{background:white;border-radius:14px;padding:20px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.field{display:flex;flex-direction:column;gap:6px}.field input,.field select,.field textarea{padding:11px;border:1px solid #ddd;border-radius:8px;font:inherit}.field textarea{min-height:120px;font-family:monospace}.btn{background:#e53935;color:white;border:0;padding:11px 16px;border-radius:8px;cursor:pointer}.msg{background:#fff4df;padding:12px;border-radius:8px;margin:12px 0}.products{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px}.products a{padding:12px;background:white;border:1px solid #eee;border-radius:9px;color:#222;text-decoration:none}.products a:hover{border-color:#e53935}</style></head><body><header class="top"><b>Xiaomi Store · Fichas técnicas</b>　<a href="index.php">Panel</a><a href="productos.php">Productos</a><a href="gestion.php">Módulos comerciales</a></header><main class="wrap"><h1>Fichas técnicas de productos</h1><p>Administra SKU, marca, precio anterior, garantía, especificaciones y galería. Los campos JSON deben respetar el formato indicado.</p><?php if($message):?><div class="msg"><?=h($message)?></div><?php endif?><section class="panel"><h2>Selecciona un producto</h2><div class="products"><?php foreach($products as $x):?><a href="?id=<?=$x['id']?>"><b><?=h($x['nombre'])?></b><br><small>ID <?=$x['id']?> · S/ <?=number_format($x['precio'],2)?></small><br><small><?=!empty($x['sku'])?'SKU: '.h($x['sku']):'Sin ficha ampliada'?></small></a><?php endforeach?></div></section><?php if($current):?><section class="panel"><h2><?=h($current['nombre'])?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="producto_id" value="<?=$current['id']?>"><div class="grid"><label class="field">SKU<input name="sku" value="<?=h($current['sku'])?>"></label><label class="field">Marca<input name="marca" value="<?=h($current['marca']??'Xiaomi')?>"></label><label class="field">Precio anterior (S/)<input type="number" min="0" step="0.01" name="precio_anterior" value="<?=h($current['precio_anterior'])?>"></label><label class="field">Garantía<input name="garantia" value="<?=h($current['garantia'])?>" placeholder="Ej. 12 meses"></label></div><p class="field">Especificaciones (JSON objeto)<textarea name="especificaciones"><?=h($current['especificaciones']?:'{}')?></textarea></p><p class="field">Galería de imágenes (JSON arreglo de URL o rutas)<textarea name="galeria"><?=h($current['galeria']?:'[]')?></textarea></p><label><input type="checkbox" name="destacado" <?=$current['destacado']?'checked':''?>> Producto destacado</label><p><button class="btn">Guardar ficha técnica</button></p></form><p><small>Ejemplo de especificaciones: {"Pantalla":"AMOLED 6.67 pulgadas","Memoria":"8 GB RAM / 256 GB","Batería":"5000 mAh"}</small></p></section><?php endif?></main></body></html>
